#define rot(a) mat2(cos(a+vec4(0,33,11,0)))                      // rotation

vec4 C;

float SDF( vec3 q) {                                             // --- shape SDF
    C = textureLod(iChannel0, floor((q.xz-.5)*32.)/32., 2.);     // heigth = texture.r
    return max( q.y - .1*C.r, length(fract(q.xz*32.)-.5)/32. );  // grid of cylinders
}

void mainImage( out vec4 O, vec2 u ) {

    vec3 R = iResolution,
#if 1                                                            // perspective
         P = vec3(0, 0, 1), q,                                   // view position then ray sample
         D = normalize(vec3( u - .5*R.xy, -R.y )),               // ray direction
         M = 6.*( iMouse.z > 0. ? iMouse.xyz/R - vec3(0,.7,0) :  // ( comment for no mouse cam )
                   vec3(.5,.95,0) + vec3(.1,.05,0) * cos(.3*iTime + vec3(0,11,0)) );
#else                                                            // isometric      
         P = vec3( (u - .5*R.xy)/R.y, -2. ), q,                  // view position then ray sample
         D = vec3(0,0,1),                                        // ray direction
         M = 6.*( iMouse.z > 0. ? iMouse.xyz/R -.5 :             // ( comment for no mouse cam )
                   vec3(0,.15,0) + vec3(.2,.1,0) * cos(.3*iTime + vec3(0,11,0)) );
#endif         

    P.yz *= rot(M.y),                                            // rotations
    P.xz *= rot(M.x);
    D.yz *= rot(M.y),                              
    D.xz *= rot(M.x);

    float s = 1.5, h=1.;                                         // scaling       
    for ( O=vec4(1); O.x > 0. && h > .01; O-=.01 ) {             // --- march scene
        q = P/s,
        h = min( h, SDF(q) ),
        P += .5* h*D;
    }    
                                                                 // --- color scheme
    vec3 e = vec3(.001,0,0),                                     // compute normal
         N = normalize( vec3( SDF(q+e), SDF(q+e.yxy), SDF(q+e.yyx) ) - h );
    O *= (1.+C)/2.                                               // color
      *  ( .5+.5*dot(N, vec3(-1,1,-1))/1.73)                     // shading
      * O*O * 1.2;                                               // pseudo AO
}
